Scripts.OnLoad:
ADKP_PrepareFrame(self);
ADKP_LegacyCall(self, "OnLoad", function()
ADKP_ApplyBackdrop(self, {bgFile = "Interface\\TutorialFrame\\TutorialFrameBackground", edgeFile = "Interface\\DialogFrame\\UI-DialogBox-Border", tile = true, tileSize = 16, edgeSize = 16, insets = {left = 5, right = 5, top = 5, bottom = 5}});

end);

ADKP_PrepareFrame(self);
ADKP_LegacyCall(self, "OnLoad", function()

            ADKP_GetGlobal(this:GetParent():GetName().."Cost"):SetAutoFocus( false );
            this:SetBackdropColor(0, 0, 0, 0.6);
            this:SetBackdropBorderColor(0.5, 0.5, 0.5, 1);

end);

Scripts.OnClick:
ADKP_LegacyCall(self, "OnClick", function()

            local cost = ADKP_GetGlobal(this:GetParent():GetName().."Cost"):GetText();
            if(cost == nil) then
            cost = 0;
            end
            ADKP_AutoAward(cost);
            ADKP_PlaySound("LOOTWINDOWCOINSOUND");
            ADKP_GetGlobal(this:GetParent():GetName().."Cost"):ClearFocus();
            ADKP_AwardFrame:Hide();

end, button, down);

ADKP_LegacyCall(self, "OnClick", function()

            ADKP_PlaySound("igMainMenuClose");
            ADKP_GetGlobal(this:GetParent():GetName().."Cost"):ClearFocus();
            ADKP_AwardFrame:Hide();

end, button, down);
